function maxFrequency(nums, k, numOperations) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  let best = 0;

  let low = 0;
  let high = 0;
  let start = 0;
  while (start < n) {
    let end = start;
    while (end < n && nums[end] === nums[start]) {
      end++;
    }
    const target = nums[start];
    while (nums[low] < target - k) {
      low++;
    }
    while (high < n && nums[high] <= target + k) {
      high++;
    }
    const same = end - start;
    const reachable = high - low;
    best = Math.max(best, same + Math.min(numOperations, reachable - same));
    start = end;
  }

  let left = 0;
  for (let right = 0; right < n; right++) {
    while (nums[right] - nums[left] > 2 * k) {
      left++;
    }
    best = Math.max(best, Math.min(numOperations, right - left + 1));
  }
  return best;
}

