function maxFrequency(nums, k, numOperations) {
  // For a final value x: copies of x are free, other elements within k of x cost one operation each.
  const score = x => {
    let same = 0, near = 0;
    for (const v of nums) {
      if (v === x) same++;
      else if (Math.abs(v - x) <= k) near++;
    }
    return same + Math.min(numOperations, near);
  };
  const lowest = Math.min(...nums) - k, highest = Math.max(...nums) + k;
  let best = 0;
  if (highest - lowest <= 4000) {
    // Small range: simply try every integer target.
    for (let x = lowest; x <= highest; x++) best = Math.max(best, score(x));
  } else {
    // Otherwise an optimal target is always one of v - k, v, v + k for some element v.
    for (const v of nums) for (const x of [v - k, v, v + k]) best = Math.max(best, score(x));
  }
  return best;
}

