function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2000 - pick(50) : 1 + pick(8);
  const style = pick(4);
  let span, k;
  if (style === 0) { span = large ? 1000000000 : 20; k = pick(large ? 5000000 : 6); }
  else if (style === 1) { span = large ? 1000 : 6; k = pick(large ? 20 : 3); }
  else if (style === 2) { span = 1000000000; k = rand() < 0.5 ? 1000000000 : pick(1000000001); }
  else { span = large ? 300 : 10; k = 0; }
  const nums = Array.from({ length: n }, () => 1 + pick(span));
  const numOperations = rand() < 0.2 ? n : pick(n + 1);
  return [nums, k, numOperations];
}
